(function(){
'use strict';
const Engine=window.MiyarCompensation;if(!Engine)return;
const KEY='miyar-compensation-scenarios-v1';
const workspace=window.MiyarScenarioWorkspace.create({prefix:'cp',key:KEY,schema:'miyar-compensation-scenario/1.0',calculate:Engine.evaluate,values,fill,renderResult:result,bindResult:bind,resultAttribute:'result',fromInput:i=>({...i,targetPenetration:i.targetPenetrationPercent})});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function money(v,c){return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:2})+' '+esc(c);}
function read(){return workspace.rows();}
function save(v){return workspace.save(v);}
function field(id,label,value='',attrs=''){return '<label class="cp-field">'+label+'<input id="cp-'+id+'" value="'+esc(value)+'" '+attrs+'></label>';}
function values(){return {payBasis:document.getElementById('cp-basis').value,role:document.getElementById('cp-role').value,grade:document.getElementById('cp-grade').value,headcount:document.getElementById('cp-headcount').value,currency:document.getElementById('cp-currency').value,period:document.getElementById('cp-period').value,bandSource:document.getElementById('cp-source').value,bandMin:document.getElementById('cp-min').value,bandMid:document.getElementById('cp-mid').value,bandMax:document.getElementById('cp-max').value,targetPenetration:document.getElementById('cp-target').value,currentSalary:document.getElementById('cp-current').value,oncostPercent:document.getElementById('cp-oncost').value};}
function fill(e){for(const [k,v] of Object.entries({role:e.role,grade:e.grade,headcount:e.headcount,currency:e.currency,source:e.bandSource,min:e.bandMin,mid:e.bandMid,max:e.bandMax,target:e.targetPenetration,current:e.currentSalary,oncost:e.oncostPercent})){const el=document.getElementById('cp-'+k);if(el)el.value=v??'';}document.getElementById('cp-period').value=e.period||'monthly';document.getElementById('cp-basis').value=e.payBasis||'basic';}
function gradeFromInstitution(role){const I=window.MiyarInstitutionProfile,p=I?.read?.();if(!I||!p)return'';const g=I.matchGrade(p,role);return g?g.id+' · '+(ar()?g.labelAr:g.labelEn):'';}
function result(v){const r=v.result,i=v.input,c=i.currency,period=t(i.period==='monthly'?'شهري':'سنوي',i.period==='monthly'?'Monthly':'Annual');return '<section class="cp-result"><div class="cp-result-head"><div><span>PHASE 3 · ORGANIZATION BAND</span><h2>'+esc(i.role||t('سيناريو التعويض','Compensation scenario'))+'</h2><p>'+esc(i.grade||t('الدرجة غير محددة','Grade not specified'))+' · '+period+'</p></div><strong>'+money(r.recommendedSalary??r.targetSalary,c)+'</strong></div><div class="cp-metrics"><div><span>'+t('الحد الأدنى','Minimum')+'</span><b>'+money(i.bandMin,c)+'</b></div><div><span>'+t('المنتصف','Midpoint')+'</span><b>'+money(i.bandMid,c)+'</b></div><div><span>'+t('الحد الأعلى','Maximum')+'</span><b>'+money(i.bandMax,c)+'</b></div><div><span>'+t('موضع الهدف داخل النطاق','Target range position')+'</span><b>'+i.targetPenetrationPercent+'%</b></div><div><span>Compa-ratio</span><b>'+(r.compaRatio===null?'—':r.compaRatio)+'</b></div><div><span>'+t('إجمالي تكلفة صاحب العمل سنويًا','Annual employer cost')+'</span><b>'+money(r.annualEmployerCost,c)+'</b></div></div><div class="cp-range"><div class="cp-line"><span style="left:0%"></span><span style="left:25%"></span><span style="left:50%"></span><span style="left:75%"></span><span style="left:100%"></span><i style="left:'+i.targetPenetrationPercent+'%"></i></div><div><span>Min</span><span>25%</span><span>Mid</span><span>75%</span><span>Max</span></div></div>'+(r.adjustmentPerFte===null?'<p class="cp-note">'+t('لم يُدخل راتب حالي/مرجعي؛ لذلك تبقى نسبة Compa-ratio وتكلفة التعديل غير معروفتين بدل عرض صفر.','No current/reference salary was provided, so compa-ratio and adjustment cost remain unknown rather than displaying zero.')+'</p>':'<div class="cp-adjust"><strong>'+t('الفرق لكل FTE','Difference per FTE')+': '+money(r.adjustmentPerFte,c)+'</strong><span>'+t('الأثر السنوي شامل تكلفة صاحب العمل','Annual adjustment including employer on-cost')+': '+money(r.annualAdjustmentCost,c)+'</span></div>')+'<div class="cp-policy"><strong>'+t(r.payAction==='red-circle'?'أعلى من النطاق — تثبيت الراتب للمراجعة':r.payAction==='hold'?'تثبيت الراتب — لا تخفيض تلقائي':r.payAction==='below-band'?'أقل من النطاق — يحتاج مراجعة':'اقتراح تعويض للمراجعة',r.payAction==='red-circle'?'Above band — red-circle / hold for review':r.payAction==='hold'?'Hold salary — no automatic reduction':r.payAction==='below-band'?'Below band — review required':'Compensation proposal for review')+'</strong><p>'+t('أساس الحساب: '+(i.payBasis==='total'?'الأجر الإجمالي':'الأجر الأساسي')+'. نسبة تكلفة صاحب العمل مدخلة يدويًا؛ لا يحسب النظام اشتراكات GOSI تلقائيًا.','Pay basis: '+(i.payBasis==='total'?'total cash pay':'basic salary')+'. Employer on-cost is entered manually; GOSI contributions are not calculated automatically.')+'</p></div>'+'<div class="cp-warning"><strong>'+t('ليس Benchmark سوقي','Not a market benchmark')+'</strong><p>'+esc(t('الحساب يستخدم فقط نطاق الراتب الذي أدخلته الجهة ومصدره. لا يستنتج عدالة الأجر ولا قيمة السوق ولا يصدر اعتماد تعويضات.','The calculation uses only the organization-provided salary band and source. It does not infer pay equity, market value or compensation approval.'))+'</p></div><div class="action-row"><button type="button" class="button button-primary" data-cp-save>'+t('حفظ السيناريو','Save scenario')+'</button><button type="button" class="button button-outline" data-cp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-cp-status role="status"></p></section>';}
function bind(v){const root=document.querySelector('.cp-result');root.querySelector('[data-cp-save]').onclick=()=>{try{const r=save(v);root.querySelector('[data-cp-status]').textContent=t('حُفظ السيناريو: ','Scenario saved: ')+r.id;}catch(e){workspace.fail(e);}};root.querySelector('[data-cp-export]').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-compensation-scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};}
function render(){if(location.hash!=='#enterprise/compensation')return;const content=document.getElementById('ent-content');if(!content)return;document.getElementById('enterprise-heading').textContent=t('التعويضات','Compensation');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('التعويضات','Compensation');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-comp-nav]')?.classList.add('active');let pending=null;try{pending=JSON.parse(sessionStorage.getItem('miyar-compensation-handoff')||'null');}catch{}content.innerHTML='<section class="cp-page"><div class="cp-heading"><div><span>PHASE 3 · COMPENSATION</span><h2>'+t('اربط الدرجة بنطاق التعويض المعتمد لدى الجهة','Link the grade to the organization-approved compensation band')+'</h2><p>'+t('معيار لا يخترع رواتب سوقية. أدخل نطاق الجهة ومصدره، ثم احسب موضع الراتب والأثر على التكلفة بشكل قابل للمراجعة.','Miyar does not invent market salaries. Enter the organization band and its source, then calculate salary positioning and cost impact transparently.')+'</p></div><button type="button" class="button button-outline" data-cp-example>'+t('تحميل مثال توضيحي','Load illustrative example')+'</button></div><div class="cp-form">'+field('role',t('الدور / المنصب','Role / position'),pending?.role||'')+field('grade',t('الدرجة','Grade'),pending?.grade||gradeFromInstitution(pending?.role||''))+field('headcount',t('عدد FTE','Headcount'),pending?.headcount||1,'type="number" min="1" step="1"')+field('currency',t('العملة','Currency'),'SAR','maxlength="3"')+'<label class="cp-field">'+t('فترة النطاق','Band period')+'<select id="cp-period"><option value="monthly">'+t('شهري','Monthly')+'</option><option value="annual">'+t('سنوي','Annual')+'</option></select></label>'+'<label class="cp-field">'+t('أساس النطاق والراتب','Band and salary basis')+'<select id="cp-basis"><option value="basic">'+t('الراتب الأساسي','Basic salary')+'</option><option value="total">'+t('إجمالي الأجر النقدي','Total cash pay')+'</option></select></label>'+field('source',t('مصدر نطاق الراتب / مرجع الجهة','Salary-band source / organization reference'),'')+field('min',t('الحد الأدنى','Minimum'),'','type="number" min="0" step="any"')+field('mid',t('المنتصف','Midpoint'),'','type="number" min="0" step="any"')+field('max',t('الحد الأعلى','Maximum'),'','type="number" min="0" step="any"')+field('target',t('موضع الهدف داخل النطاق %','Target range position %'),'50','type="number" min="0" max="100" step="1"')+field('current',t('راتب حالي/مرجعي — اختياري','Current/reference salary — optional'),'','type="number" min="0" step="any"')+field('oncost',t('تكلفة صاحب العمل الإضافية %','Employer on-cost %'),'0','type="number" min="0" max="200" step="0.1"')+'</div><div class="cp-run"><button type="button" class="button button-primary" data-cp-run>'+t('احسب موضع التعويض','Calculate compensation position')+'</button><span data-cp-message role="status">'+t('يجب أن يكون النطاق من مصدر داخلي معتمد أو مبرر موثق.','The band must come from an approved internal source or documented rationale.')+'</span></div><div data-cp-result></div></section>';sessionStorage.removeItem('miyar-compensation-handoff');content.querySelector('[data-cp-example]').onclick=()=>workspace.example(Engine.example);content.querySelector('[data-cp-run]').onclick=()=>workspace.calculate();if(pending)workspace.example({...pending,period:'monthly',currency:'SAR',targetPenetration:50,oncostPercent:0});workspace.mount(content);}

function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-comp-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/compensation';link.className='nav-link';link.dataset.compNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v12H4zM7 4h10v3M8 12h8m-4-3v6"/></svg><span>'+t('التعويضات','Compensation')+'</span>';const mp=nav.querySelector('[data-manpower-nav]'),grade=nav.querySelector('[data-enterprise-open="grading"]');(mp||grade)?.after(link);}else link.querySelector('span').textContent=t('التعويضات','Compensation');}
function injectManpowerLink(){if(location.hash!=='#enterprise/manpower')return;const actions=document.querySelector('.mp-results .action-row'),plan=window.MiyarManpowerWorkbench?.getResult?.();if(!actions||actions.querySelector('[data-cp-from-mp]')||!plan||plan.scenarios.base.final.rawGapFte<=.5)return;const btn=document.createElement('button');btn.type='button';btn.className='button button-outline';btn.dataset.cpFromMp='true';btn.textContent=t('احسب أثر التعويض','Estimate compensation impact');actions.append(btn);btn.onclick=()=>{const current=window.MiyarManpowerWorkbench.getResult();if(!current||current.scenarios.base.final.rawGapFte<=.5)return;sessionStorage.setItem('miyar-compensation-handoff',JSON.stringify({role:current.input.role,grade:gradeFromInstitution(current.input.role),headcount:current.scenarios.base.final.gapHeadcount}));location.hash='#enterprise/compensation';};}
window.addEventListener('miyar:scenario-result',e=>{if(e.detail.prefix==='mp')injectManpowerLink();});
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-comp-nav]');if(link){e.preventDefault();location.hash='#enterprise/compensation';setTimeout(render,0);}if(e.target.closest('[data-mp-run]'))setTimeout(injectManpowerLink,0);});setTimeout(()=>{ensureNav();render();injectManpowerLink();},0);window.MiyarCompensationWorkbench={KEY,read,render};
})();
